"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFaqContent } from "./components/faq-blocks/content";
import View0 from "./components/faq-blocks/variants/01-numbered";
const variants = {"numbered":View0};
export type { ArtemisFaqContact, ArtemisFaqContent, ArtemisFaqLink, ArtemisFaqQuestion, ArtemisFaqSearch } from "./components/faq-blocks/content";
export interface ArtemisFaqBlocksProps { className?: string; variant?: "numbered"; /** The words on the FAQ section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFaqContent>; }
export function ArtemisFaqBlocks({ className, variant = "numbered", content }: ArtemisFaqBlocksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisFaqLink {
  label: string;
  href: string;
}

/** A question and its answer. */
export interface ArtemisFaqQuestion {
  /** The question, on the row that opens. */
  question: string;
  /** The answer, shown while the row is open. */
  answer: string;
  /** A short slug, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
  /** The topic it belongs to. search shows it on the row and adds a filter tab for each topic, in the order the topics first appear; with no topics it shows no tabs. */
  category?: string;
}

/** A card beside the questions that points to a person. */
export interface ArtemisFaqContact {
  /** A small line over the title. split. */
  label?: string;
  /** The card's heading. */
  title: string;
  /** The paragraph under the heading. */
  description: string;
  /** The card's button. */
  cta: ArtemisFaqLink;
}

/** The words on the search box, its topic tabs and its empty result. */
export interface ArtemisFaqSearch {
  /** The hint in the empty search box. */
  placeholder: string;
  /** The first topic tab, which shows every question. */
  allLabel: string;
  /** The heading shown when no question matches. */
  emptyTitle: string;
  /** The line under that heading. */
  emptyText: string;
}

/** The words on an Artemis FAQ section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFaqContent {
  /** The short line above the heading. All layouts. */
  badge: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's last words. stacked underlines them; the other layouts run them on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The questions, each opening to show its answer. All layouts. numbered and split number them; numbered, ai-workspace, split and search open one at a time, starting with the first; stacked opens any number, starting with the first two. */
  questions: ArtemisFaqQuestion[];
  /** A card with a button beside the questions. ai-workspace and split. */
  contact?: ArtemisFaqContact;
  /** The words on the search box, the topic tabs and the empty result. search. */
  search?: ArtemisFaqSearch;
}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT, ARTEMIS_EASE_OUT_CSS } from "../../../lib/ease";
import type { ArtemisFaqContent } from "../content";
const DEFAULT = {
    badge: "Good to know",
    headline: "A clear answer for every question.",
    subhead: "Everything you need to understand the product, your plan, and what happens next.",
    questions: [
        { id: "trial", question: "Can I try the product before choosing a plan?", answer: "Yes. Every workspace starts with a 14-day trial, and you can explore the full product without adding a payment method." },
        { id: "invite", question: "How do I bring my team in?", answer: "Invite people by email or share a private join link. You can change roles and access at any time from workspace settings." },
        { id: "import", question: "Can I move my existing work over?", answer: "You can import common file formats or start from a template. Our support team can also help with larger moves." },
        { id: "plans", question: "What is included in each plan?", answer: "Every plan includes the core workspace. Higher plans add more guests, longer history, and organization controls for larger teams." },
        { id: "change-plan", question: "Can I change my plan later?", answer: "Anytime. Upgrades take effect immediately, while downgrades begin at the end of your current billing period." },
        { id: "annual", question: "Do you offer annual billing?", answer: "Yes. Annual plans include two months at no additional cost and use the same features and support as monthly plans." },
    ],
} satisfies ArtemisFaqContent;
const hidden = { opacity: 0, filter: "blur(8px)", y: 18 };
const shown = { opacity: 1, filter: "blur(0px)", y: 0 };
export default function FaqBlocksNumbered({ content }: { content?: Partial<ArtemisFaqContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const reduce = useReducedMotion();
    const baseId = useId();
    const [active, setActive] = useState<number | null>(0);
    return (<>
      <section className="art:w-full art:bg-background art:px-4 art:py-16 art:font-sans art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24">
        <div className="art:mx-auto art:w-full art:max-w-6xl">
          <motion.header className="art:mx-auto art:max-w-2xl art:pb-10 art:text-center art:@min-[640px]/artemis:pb-12" initial={hidden} animate={shown} transition={reduce ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.05 }}>
            <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.16em]">
              {copy.badge}
            </p>
            <h2 className="art:mt-5 art:text-balance art:font-medium art:text-4xl art:leading-none art:tracking-tight">
              {copy.headlineAccent ? `${copy.headline} ${copy.headlineAccent}` : copy.headline}
            </h2>
            <p className="art:mx-auto art:mt-5 art:max-w-xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base">
              {copy.subhead}
            </p>
          </motion.header>
          <div className="art:mx-auto art:max-w-4xl art:overflow-hidden">
            {copy.questions.map((item, index) => {
            const id = item.id ?? `q${index}`;
            const open = active === index;
            const triggerId = `${baseId}-${id}-trigger`;
            const contentId = `${baseId}-${id}-content`;
            return (<motion.article layout="position" key={id} className="art:border-border art:border-b art:last:border-b-0" initial={hidden} animate={shown} transition={reduce ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.12 + index * 0.065 }}>
                  <ArtemisButton variant="link" size="none" className="art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:group art:grid art:min-h-24 art:w-full art:grid-cols-[2rem_1fr] art:items-start art:gap-3 art:px-4 art:py-7 art:text-left art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-ring art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-8 art:@min-[1024px]/artemis:px-8 art:rounded-full" id={triggerId} aria-expanded={open} aria-controls={contentId} tabIndex={0} onClick={() => setActive(open ? null : index)} whileTap={reduce ? undefined : { scale: 0.99 }}>
                    <span aria-hidden="true" className={`art:shrink-0 art:pt-1 art:font-mono art:font-medium art:text-sm art:tabular-nums art:transition-colors art:duration-200 ${open ? "art:text-foreground" : "art:text-muted-foreground/55 art:group-hover:text-muted-foreground"}`}>{String(index + 1).padStart(2, "0")}</span>
                    <span className={`art:max-w-3xl art:text-balance art:font-medium art:text-xl art:leading-7 art:tracking-tight art:transition-colors art:duration-200 ${open ? "art:text-foreground" : "art:text-muted-foreground art:group-hover:text-foreground"}`}>{item.question}</span>
                  </ArtemisButton>
                  <section id={contentId} aria-labelledby={triggerId} aria-hidden={!open} style={{ transitionTimingFunction: ARTEMIS_EASE_OUT_CSS }} className={`art:grid art:overflow-hidden art:transition-[grid-template-rows] art:duration-300 art:motion-reduce:transition-none ${open ? "art:grid-rows-[1fr]" : "art:grid-rows-[0fr]"}`}>
                    <div className="art:grid art:min-h-0 art:grid-cols-[2rem_1fr] art:gap-3 art:overflow-hidden art:px-4 art:@min-[640px]/artemis:px-6 art:@min-[1024px]/artemis:px-8">
                      <p style={{ transitionTimingFunction: ARTEMIS_EASE_OUT_CSS }} className={`art:col-start-2 art:max-w-3xl art:pb-8 art:text-left art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:transition-[opacity,transform] art:duration-200 art:motion-reduce:transition-none art:@min-[640px]/artemis:pb-9 ${open ? "art:translate-y-0 art:opacity-100" : "art:-translate-y-1 art:opacity-0"}`}>{item.answer}</p>
                    </div>
                  </section>
                </motion.article>);
        })}
          </div>
        </div>
      </section>
    </>);
}
